// 1. Safely collect ALL data from the workflow
const jsons = [];
try { jsons.push($items('FAL AI Credits')[0]?.json); } catch(e) {}
try { jsons.push($items('Open Router Credits')[0]?.json); } catch(e) {}
try { jsons.push($items('APIFY Credits')[0]?.json); } catch(e) {}

// 2. DEEP SEARCH FUNCTION: Recursively hunts for exact keys
function findValue(keys) {
  let result = null;
  function search(obj) {
    if (result !== null) return;
    if (typeof obj !== 'object' || obj === null) return;
    for (let k of keys) {
      if (obj[k] !== undefined && obj[k] !== null) {
        let val = parseFloat(obj[k]);
        if (!isNaN(val)) { result = val; return; }
      }
    }
    for (let k in obj) search(obj[k]);
  }
  jsons.forEach(search);
  return result;
}

// 3. Extract exact values from the proper billing endpoints
// FAL AI
const falBalance = findValue(['current_balance']);

// OpenRouter (/api/v1/credits returns 'total_credits' and 'total_usage')
const orTotalCredits = findValue(['total_credits']);
const orTotalUsage   = findValue(['total_usage']);

// Apify (/v2/users/me/usage/monthly returns USD amounts directly)
// We look for 'totalUsageCreditsUsd' (Used) and 'monthlyUsageLimitUsd' or 'maxMonthlyUsageUsd' (Plan)
const apifyUsedUsd = findValue(['totalUsageCreditsUsd', 'totalUsageCreditsUsdAfterVolumeDiscount']);
// To get the plan limit dynamically, we check the general limits (usually stored as maxMonthlyUsageUsd)
const apifyPlanUsd = findValue(['maxMonthlyUsageUsd', 'monthlyUsageLimitUsd', 'subscriptionLimitUsd']) ?? 29.00; // Apify usually hides the total plan limit in the /usage endpoint, but we grab the used USD directly.

// 4. Calculate & Format Strings
const falStr = falBalance !== null ? `$${falBalance.toFixed(2)}` : 'N/A';

// OpenRouter math: (total_credits - total_usage)
let orBalanceStr = 'N/A';
let orUsedStr    = 'N/A';
if (orTotalCredits !== null && orTotalUsage !== null) {
  orBalanceStr = `$${(orTotalCredits - orTotalUsage).toFixed(2)}`;
  orUsedStr    = `$${orTotalUsage.toFixed(4)}`;
}

// Apify formatting
const apUsedStr = apifyUsedUsd !== null ? `$${apifyUsedUsd.toFixed(2)}` : 'N/A';
const apPlanStr = apifyPlanUsd !== null ? `$${apifyPlanUsd.toFixed(2)}` : 'N/A';
const apAvailStr = (apifyPlanUsd !== null && apifyUsedUsd !== null)
  ? `$${(apifyPlanUsd - apifyUsedUsd).toFixed(2)}`
  : 'N/A';

// 5. Timestamp & Message
const now = new Date().toLocaleString('en-IN', {
  timeZone: 'Asia/Kolkata',
  day: '2-digit', month: 'short', year: 'numeric',
  hour: '2-digit', minute: '2-digit', hour12: true
});

const message =
`📊 <b>AI Tools — Daily Spend Report</b>
📅 ${now}
━━━━━━━━━━━━━━━━━━━━

🎨 <b>FAL AI</b>  <i>(Image Generation)</i>
├ Balance Remaining: <b>${falStr}</b>

🤖 <b>OpenRouter</b>  <i>(LLM / AI Models)</i>
├ Total Balance: <b>${orBalanceStr}</b>
└ Credits Used: <b>${orUsedStr}</b>

🕷 <b>Apify</b>  <i>(Web Scraping)</i>
├ Monthly Plan: <b>${apPlanStr}</b>
├ Used This Month: <b>${apUsedStr}</b>
└ Balance Available: <b>${apAvailStr}</b>

━━━━━━━━━━━━━━━━━━━━
📋 <a href="https://docs.google.com/spreadsheets/d/1NzUyg2REHooSmN2DqOWWUAnrrvuuBLyUq6jtb1KR5Zw/edit?gid=0#gid=0">View Google Sheet</a>`;

return [{ json: { message } }];
